package com.cratesmp.crateshop.listener;
import com.cratesmp.crateshop.CRATEShop; import com.cratesmp.crateshop.gui.ShopMenu; import com.cratesmp.crateshop.shop.ShopManager.ShopItem; import com.cratesmp.crateshop.shop.ShopManager; import org.bukkit.ChatColor; import org.bukkit.entity.Player; import org.bukkit.entity.Villager; import org.bukkit.event.*; import org.bukkit.event.inventory.InventoryClickEvent; import org.bukkit.event.player.PlayerInteractEntityEvent; import org.bukkit.persistence.PersistentDataType; import org.bukkit.NamespacedKey; import org.bukkit.inventory.EquipmentSlot;
public final class ShopListener implements Listener { private final CRATEShop plugin; private final ShopMenu menu; private final ShopManager manager; private final NamespacedKey npcKey;
 public ShopListener(CRATEShop p,ShopMenu m,ShopManager s){plugin=p;menu=m;manager=s;npcKey=new NamespacedKey(p,"shop_npc");}
 @EventHandler public void click(InventoryClickEvent e){if(!(e.getWhoClicked() instanceof Player p)||!(e.getInventory().getHolder() instanceof ShopMenu.ShopHolder))return;e.setCancelled(true); if(e.getCurrentItem()==null)return;ShopItem it=menu.itemAt(e.getInventory(),e.getRawSlot());if(it==null)return;int amount=e.isShiftClick()?16:1;boolean ok;if(e.isLeftClick())ok=manager.buy(p,it,amount);else if(e.isRightClick())ok=manager.sell(p,it,amount);else return;if(!ok){p.sendMessage("§cNon puoi completare questa operazione. Controlla soldi, spazio e oggetti.");return;}p.sendMessage("§aOperazione completata: §f"+amount+"x "+ChatColor.stripColor(ChatColor.translateAlternateColorCodes('&',it.display())));}
 @EventHandler public void npc(PlayerInteractEntityEvent e){if(e.getHand()!=EquipmentSlot.HAND)return;if(!(e.getRightClicked() instanceof Villager v))return;if(v.getPersistentDataContainer().has(npcKey,PersistentDataType.BYTE)){e.setCancelled(true);menu.open(e.getPlayer());}}
 public NamespacedKey npcKey(){return npcKey;}
}
